// Normaliza o pedido do painel, aplica as regras de acesso e carrega a memória da sessão.

// ---------------------------------------------------------------------------
// CONFIGURAÇÃO
// ---------------------------------------------------------------------------
const MODELO_PADRAO = 'nvidia/nemotron-3-super-120b-a12b:free';
const MODELOS_PERMITIDOS = [MODELO_PADRAO]; // outros modelos aceitos no campo modelo_llm
const ACEITAR_MODELOS_GRATUITOS = true; // aceita qualquer modelo terminado em ":free"
const CHAVE_PAINEL = ''; // se preenchida, o painel precisa enviar o cabeçalho x-kovan-key com este valor
const MODO_APROVACAO = 'estrito'; // 'estrito': a etapa só avança com aprovação humana | 'proposta': roda tudo e marca como pendente
const LIMITE_PERGUNTA = 2000; // caracteres
// ---------------------------------------------------------------------------

const req = $input.first().json || {};
const body = req.body || {};
const headers = req.headers || {};

function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim();
}

function aprovacoesVazias() {
  return {
    diagnostico: { status: 'pendente', nota: '', quando: '', escopo: '' },
    fila: { status: 'pendente', nota: '', quando: '' },
    plano: { status: 'pendente', nota: '', quando: '' },
  };
}

const avisos = [];
let valido = true;
let status = 200;
let erro = '';

// 1) Acesso e campos obrigatórios
const pergunta = String(body.pergunta == null ? '' : body.pergunta).trim().slice(0, LIMITE_PERGUNTA);
if (CHAVE_PAINEL && String(headers['x-kovan-key'] || '') !== CHAVE_PAINEL) {
  valido = false;
  status = 401;
  erro = 'Acesso não autorizado: chave do painel ausente ou incorreta.';
} else if (!pergunta) {
  valido = false;
  status = 400;
  erro = 'Envie uma pergunta no campo "pergunta".';
}

// 2) Modelo de linguagem: só aceita o que estiver liberado
let modeloLlm = MODELO_PADRAO;
const modeloPedido = String(body.modelo_llm || '').trim();
if (modeloPedido) {
  const liberado =
    MODELOS_PERMITIDOS.includes(modeloPedido) || (ACEITAR_MODELOS_GRATUITOS && /:free$/.test(modeloPedido));
  if (liberado) modeloLlm = modeloPedido;
  else avisos.push('O modelo "' + modeloPedido + '" não está liberado; usei o modelo padrão.');
}

// 3) Dados do ciclo enviados pelo painel
const contas = Array.isArray(body.contas) ? body.contas : body.contas ? [body.contas] : [];
const resumoModelo = body.modelo && typeof body.modelo === 'object' ? body.modelo : {};
if (valido && !contas.length) avisos.push('O painel não enviou contas na fila do ciclo.');

// 4) Sessão: aprovações e respostas guardadas das rodadas anteriores
let sessionId = String(body.sessionId || '').trim();
const sessaoFixa = !!sessionId;
if (!sessionId) sessionId = 'exec-' + ($execution && $execution.id ? $execution.id : Date.now());

let sessao = null;
try {
  const memoria = $getWorkflowStaticData('global');
  const salva = memoria.sessoes && memoria.sessoes[sessionId];
  if (salva) sessao = JSON.parse(JSON.stringify(salva));
} catch (e) {
  avisos.push('A memória da sessão não está disponível nesta execução.');
}
if (!sessao) sessao = {};
sessao.foco = sessao.foco || '';
sessao.aprovacoes = Object.assign(aprovacoesVazias(), sessao.aprovacoes || {});
sessao.respostas = sessao.respostas || {};
sessao.aguardando = sessao.aguardando || '';
sessao.ultimaPergunta = sessao.ultimaPergunta || '';

if ($execution && $execution.mode === 'test') {
  avisos.push('Execução de teste: a memória da sessão só é gravada com o workflow ativo, pela URL de produção.');
}

// 5) Decisões humanas escritas na conversa (ex.: "Confirmo o diagnóstico")
// A decisão é lida só no trecho antes dos dois-pontos: o que vem depois é a nota de quem decidiu.
const t = norm(pergunta);
const cabeca = norm(pergunta.split(':')[0]);
const comandos = [];
const temInterrogacao = t.includes('?');
const temNegacao = /\bnao\s+(\w+\s+){0,2}(confirm|valid|aprov)/.test(cabeca);
const pareceDuvida =
  /^\W*(me diga|me fale|quero saber|gostaria de saber|sabe se|qual|quais|como|quando|quem|por que|porque|sera que)\b/.test(cabeca) ||
  /\bse\s+(o|a)\s+(diagnostico|fila|plano)\b/.test(cabeca);

const VERBO = {
  confirmar: '(confirmo|confirmei|confirmamos|confirmado|valido|validei|validamos|validado)',
  aprovar: '(aprovo|aprovei|aprovamos|aprovou|aprovado|aprovada)',
  ajustar: '(ajusto|ajustei|ajustamos|ajustou|ajustado|ajustada|reordeno|reordenei|reordenou|reordenada)',
  contestar: '(contesto|contestei|contestamos|contestado)',
  rejeitar: '(rejeito|rejeitei|rejeitamos|rejeitou|rejeitado|rejeitada|reprovo|reprovei|reprovou|reprovado|reprovada)',
};
const ARTIGO = '(o\\s+|a\\s+|esse\\s+|essa\\s+|este\\s+|esta\\s+)?';
const LIGACAO = '(foi\\s+|esta\\s+|fica\\s+)?';

function disse(verbo, objeto) {
  const antes = new RegExp('\\b' + verbo + '\\s+' + ARTIGO + objeto + '\\b');
  const depois = new RegExp('\\b' + objeto + '\\s+' + LIGACAO + verbo + '\\b');
  return antes.test(cabeca) || depois.test(cabeca);
}

function notaDoUsuario() {
  const i = pergunta.indexOf(':');
  return i >= 0 ? pergunta.slice(i + 1).trim() : '';
}

if (valido && !temInterrogacao && !temNegacao && !pareceDuvida) {
  if (disse(VERBO.contestar, 'diagnostico')) {
    comandos.push({ etapa: 'diagnostico', status: 'contestado', nota: notaDoUsuario() });
  } else if (disse(VERBO.ajustar, 'diagnostico')) {
    comandos.push({ etapa: 'diagnostico', status: 'ajustado', nota: notaDoUsuario() });
  } else if (disse(VERBO.confirmar, 'diagnostico')) {
    comandos.push({ etapa: 'diagnostico', status: 'validado', nota: '' });
  }

  if (disse(VERBO.rejeitar, 'fila')) {
    comandos.push({ etapa: 'fila', status: 'rejeitada', nota: notaDoUsuario() });
  } else if (disse(VERBO.ajustar, 'fila')) {
    comandos.push({ etapa: 'fila', status: 'ajustada', nota: notaDoUsuario() });
  } else if (disse(VERBO.aprovar, 'fila')) {
    comandos.push({ etapa: 'fila', status: 'aprovada', nota: '' });
  }

  if (disse(VERBO.rejeitar, 'plano')) {
    comandos.push({ etapa: 'plano', status: 'rejeitado', nota: notaDoUsuario() });
  } else if (disse(VERBO.ajustar, 'plano')) {
    comandos.push({ etapa: 'plano', status: 'ajustado', nota: notaDoUsuario() });
  } else if (disse(VERBO.aprovar, 'plano')) {
    comandos.push({ etapa: 'plano', status: 'aprovado', nota: '' });
  }

  // Resposta curta ("Confirmo", "Aprovado") vale para a etapa que a conversa está aguardando
  const respostaCurta = /^\W*((ok|sim|certo)\W+)?(confirmo|confirmado|aprovo|aprovado|aprovada|valido|validado|de acordo)\W*$/;
  if (!comandos.length && respostaCurta.test(cabeca)) {
    const etapa = sessao.aguardando || 'diagnostico';
    const statusDaEtapa = { diagnostico: 'validado', fila: 'aprovada', plano: 'aprovado' }[etapa];
    comandos.push({ etapa: etapa, status: statusDaEtapa, nota: '' });
  }
}

// Pedido explícito de nova versão: libera o agente mesmo que a versão anterior já esteja aprovada
const refazer =
  !comandos.length &&
  (/\b(refaca|refazer|refaz|reavalie|reavaliar|recalcule|recalcular)\b/.test(t) ||
    /\bnov[oa]\s+(diagnostico|fila|plano|analise)\b/.test(t));

// 6) Aprovações enviadas pelo painel em formato estruturado (opcional)
const aprovCorpo = {};
const STATUS_ACEITOS = {
  diagnostico: ['pendente', 'validado', 'ajustado', 'contestado'],
  fila: ['pendente', 'aprovada', 'ajustada', 'rejeitada'],
  plano: ['pendente', 'aprovado', 'ajustado', 'rejeitado'],
};
if (body.aprovacoes && typeof body.aprovacoes === 'object') {
  for (const etapa of Object.keys(STATUS_ACEITOS)) {
    const bruto = body.aprovacoes[etapa];
    const valor = norm(bruto && typeof bruto === 'object' ? bruto.status : bruto);
    if (STATUS_ACEITOS[etapa].includes(valor)) aprovCorpo[etapa] = valor;
  }
}

// 7) Resumo da conversa para o roteador
const guardadas = Object.keys(sessao.respostas).filter((k) => sessao.respostas[k]);
const resumoSessao = sessao.ultimaPergunta
  ? 'Pergunta anterior: "' +
    sessao.ultimaPergunta +
    '". Agentes com resposta guardada: ' +
    (guardadas.length ? guardadas.join(', ') : 'nenhum') +
    '. Aprovações: diagnóstico ' +
    sessao.aprovacoes.diagnostico.status +
    ', fila ' +
    sessao.aprovacoes.fila.status +
    ', plano ' +
    sessao.aprovacoes.plano.status +
    '.'
  : 'Nenhuma: esta é a primeira pergunta da conversa.';

return [
  {
    json: {
      valido: valido,
      status: status,
      erro: erro,
      pergunta: pergunta,
      sessionId: sessionId,
      sessaoFixa: sessaoFixa,
      modeloLlm: modeloLlm,
      modo: MODO_APROVACAO === 'proposta' ? 'proposta' : 'estrito',
      avisos: avisos,
      totalContas: contas.length,
      resumoModeloTxt: JSON.stringify(resumoModelo),
      filaTxt: JSON.stringify(contas),
      comandos: comandos,
      refazer: refazer,
      aprovCorpo: aprovCorpo,
      sessao: sessao,
      focoAnterior: sessao.foco,
      resumoSessao: resumoSessao,
      precisaRoteador: valido && comandos.length === 0,
    },
  },
];

// Pedido recusado antes de chegar aos agentes (pergunta vazia ou acesso negado).
// A resposta mantém o formato que o painel já conhece.
const pedido = $input.first().json || {};
const texto = 'Resposta: ' + (pedido.erro || 'pedido inválido.');

return [
  {
    json: {
      status: pedido.status || 400,
      corpo: {
        modelo: pedido.modeloLlm || '',
        agentes: [{ nome: 'Orquestrador', papel: 'Síntese e aprovações', texto: texto, status: 'erro' }],
        orquestrador: { resposta: texto },
        aprovacoes_pendentes: [],
        avisos: pedido.avisos || [],
        erro: pedido.erro || '',
      },
    },
  },
];

