// Orquestrador, parte determinística: aplica as decisões humanas, os pré-requisitos e os portões
// de aprovação sobre o plano sugerido pelo roteador, e monta o estado que percorre o restante do fluxo.

const base = JSON.parse(JSON.stringify($('Preparar pedido').first().json));
const entrada = $input.first().json || {};

const ORDEM = ['atlas', 'vera', 'ciro', 'diana', 'elias'];
const NOMES = { atlas: 'Atlas', vera: 'Vera', ciro: 'Ciro', diana: 'Diana', elias: 'Elias' };
const PAPEIS = {
  atlas: 'Diagnóstico de Risco',
  vera: 'Saúde do Relacionamento',
  ciro: 'Priorização da Fila',
  diana: 'Playbook de Retenção',
  elias: 'Mensuração e Aprendizado',
};

const estrito = base.modo !== 'proposta';
const agora = new Date().toISOString();
const avisos = (base.avisos || []).slice();
const sess = base.sessao || {};

function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function ehContaEspecifica(f) {
  const n = norm(f);
  return n !== '' && n !== 'lote';
}

function mesmaConta(a, b) {
  const x = norm(a);
  const y = norm(b);
  if (!x || !y) return false;
  if (x === y) return true;
  return (x.length >= 3 && y.includes(x)) || (y.length >= 3 && x.includes(y));
}

function pendente(extra) {
  return Object.assign({ status: 'pendente', nota: '', quando: '' }, extra || {});
}

function aprovacoesVazias() {
  return { diagnostico: pendente({ escopo: '' }), fila: pendente(), plano: pendente() };
}

// Alguns modelos devolvem a resposta em partes; aqui tudo vira um texto só.
function textoDe(saida) {
  if (typeof saida === 'string') return saida;
  if (Array.isArray(saida)) return saida.map((p) => (p && typeof p === 'object' ? p.text || '' : String(p))).join('\n');
  return saida == null ? '' : JSON.stringify(saida);
}

// O roteador deve devolver só um objeto JSON; aqui a leitura tolera texto em volta.
function extrairPlanoDoRoteador(texto) {
  const limpo = String(texto).replace(/<think>[\s\S]*?<\/think>/gi, ' ');
  const candidatos = limpo.match(/\{[^{}]*\}/g) || [];
  for (let i = candidatos.length - 1; i >= 0; i--) {
    try {
      const obj = JSON.parse(candidatos[i]);
      if (obj && Array.isArray(obj.agentes)) return obj;
    } catch (e) {
      // tenta o candidato anterior
    }
  }
  return null;
}

// Plano de reserva, usado só quando o roteador falha.
function porPalavrasChave(pergunta) {
  const t = norm(pergunta);
  const regras = [
    ['atlas', /(risco|score|sinaliz|por que|porque|diagnost|churn|padrao|erosao|queda|mix)/],
    ['vera', /(relacionamento|contato|pipeline|oportunidade|account manager|troca de am|visita|suporte|sla|nps|cobertura)/],
    ['ciro', /(prioriz|prioridade|fila|ordem|ranking|capacidade|vaga)/],
    ['diana', /(plano|playbook|o que fazer|acao|acoes|interven|roteiro|reuniao|e-?mail|mensagem|proposta|abordagem)/],
    ['elias', /(resultado|funcion|efeito|nrr|controle|north star|mensur|falso alarme|vies)/],
  ];
  const escolhidos = regras.filter((r) => r[1].test(t)).map((r) => r[0]);
  if (!escolhidos.length) return ['atlas', 'vera'];
  if (escolhidos.includes('atlas') && !escolhidos.includes('vera')) escolhidos.push('vera');
  return escolhidos;
}

// 1) Agentes pedidos nesta rodada
const temComandos = (base.comandos || []).length > 0;
let pedidos = [];
let focoPedido = '';
let origem = 'aprovacao';
let motivoRoteador = '';
if (!temComandos) {
  const lido = entrada.output ? extrairPlanoDoRoteador(textoDe(entrada.output)) : null;
  if (lido) {
    origem = 'roteador';
    pedidos = lido.agentes.map(norm);
    focoPedido = typeof lido.conta_foco === 'string' ? lido.conta_foco.trim() : '';
    motivoRoteador = typeof lido.motivo === 'string' ? lido.motivo.trim() : '';
  } else {
    origem = 'regras';
    pedidos = porPalavrasChave(base.pergunta);
    avisos.push('O roteador não respondeu em formato válido; os agentes foram escolhidos por palavras-chave.');
  }
}
pedidos = ORDEM.filter((a) => pedidos.includes(a));
const pedidosDaPergunta = pedidos.slice();

// 2) Conta em foco. Trocar de uma conta para outra abre um caso novo: as aprovações não se transferem.
let foco = sess.foco || '';
let mudouConta = false;
if (!temComandos && ehContaEspecifica(focoPedido)) {
  if (ehContaEspecifica(foco) && !mesmaConta(foco, focoPedido)) mudouConta = true;
  if (!ehContaEspecifica(foco) || mudouConta) foco = focoPedido;
}
if (!foco) foco = 'lote';

const aprov = mudouConta ? aprovacoesVazias() : Object.assign(aprovacoesVazias(), sess.aprovacoes || {});
const anteriores = mudouConta ? {} : Object.assign({}, sess.respostas || {});
if (mudouConta) {
  avisos.push(
    'A conta em foco mudou de "' + sess.foco + '" para "' + foco + '": as aprovações da conta anterior não valem para a nova.'
  );
}

// 3) Aprovações informadas pelo painel em formato estruturado
const doPainel = base.aprovCorpo || {};
for (const etapa of Object.keys(doPainel)) {
  if (aprov[etapa].status !== doPainel[etapa]) {
    aprov[etapa] = pendente({ status: doPainel[etapa], quando: agora, origem: 'painel' });
    if (etapa === 'diagnostico') aprov.diagnostico.escopo = foco;
  }
}

// 4) Decisões escritas na conversa. Só valem se existir o que aprovar nesta conversa.
const sessaoConhecida = !!sess.ultimaPergunta;
const AGENTE_DA_ETAPA = { diagnostico: 'atlas', fila: 'ciro', plano: 'diana' };
const ROTULO = { diagnostico: 'diagnóstico', fila: 'fila proposta', plano: 'plano' };
const aceitos = [];
for (const c of base.comandos || []) {
  const existeObjeto = !!anteriores[AGENTE_DA_ETAPA[c.etapa]];
  if (!existeObjeto && sessaoConhecida) {
    avisos.push('Decisão não registrada: ainda não há ' + ROTULO[c.etapa] + ' nesta conversa.');
    continue;
  }
  if (!existeObjeto) {
    avisos.push(
      'Não encontrei ' +
        ROTULO[c.etapa] +
        ' guardado nesta sessão. Os agentes rodaram de novo e a decisão vale para esta nova versão: confira antes de seguir.'
    );
  }
  aprov[c.etapa] = pendente({ status: c.status, nota: c.nota || '', quando: agora, origem: 'conversa' });
  if (c.etapa === 'diagnostico') aprov.diagnostico.escopo = foco;
  aceitos.push(c);

  // Aprovação concedida faz o fluxo avançar para a etapa seguinte
  if (c.etapa === 'diagnostico' && ['validado', 'ajustado'].includes(c.status) && !anteriores.ciro) pedidos.push('ciro');
  if (c.etapa === 'fila' && ['aprovada', 'ajustada'].includes(c.status) && !anteriores.diana) pedidos.push('diana');
}

// 5) Pedido de nova versão: a aprovação da versão anterior deixa de valer antes dos portões
if (base.refazer && !temComandos) {
  if (pedidos.includes('atlas')) aprov.diagnostico = pendente({ escopo: '' });
  if (pedidos.includes('ciro')) aprov.fila = pendente();
  if (pedidos.includes('diana')) aprov.plano = pendente();
}

const diagValidado = () => ['validado', 'ajustado'].includes(aprov.diagnostico.status);
const filaAprovada = () => ['aprovada', 'ajustada'].includes(aprov.fila.status);

// 6) O que já foi aprovado fica congelado: o agente não roda de novo, vale a versão aprovada
let reaproveitados = [];
if (!base.refazer) {
  const congelado = (a) =>
    ((a === 'atlas' || a === 'vera') && diagValidado() && !!anteriores[a]) ||
    (a === 'ciro' && filaAprovada() && !!anteriores.ciro);
  reaproveitados = pedidos.filter(congelado);
  pedidos = pedidos.filter((a) => !congelado(a));
}

// 7) Pré-requisitos: a etapa seguinte precisa da saída da anterior
const incluir = (a) => {
  if (!pedidos.includes(a)) pedidos.push(a);
};
if (pedidos.includes('diana') && !anteriores.ciro) incluir('ciro');
if ((pedidos.includes('ciro') || pedidos.includes('diana')) && !anteriores.atlas) {
  incluir('atlas');
  if (!anteriores.vera) incluir('vera');
}
pedidos = ORDEM.filter((a) => pedidos.includes(a));


// 8) Portões de aprovação humana
// Atlas, Vera e Ciro podem produzir análises preliminares.
// Diana pode elaborar um plano preliminar sem aprovação da fila.
// A geração de um plano NÃO autoriza execução operacional.
// As aprovações do Diretor Regional e do KAM continuam obrigatórias
// antes de executar qualquer intervenção.

const bloqueios = [];

if (estrito) {
  if (pedidos.includes('diana') && !filaAprovada()) {
    avisos.push(
      'Diana autorizada somente a elaborar um plano preliminar. ' +
      'A fila ainda não foi aprovada pelo Diretor Regional. ' +
      'Nenhuma intervenção operacional está autorizada.'
    );
  }
}

const plano = {};
for (const a of ORDEM) plano[a] = pedidos.includes(a);

// 9) Versão nova de uma etapa invalida a aprovação dela e o que foi produzido depois
const decidiuAgora = (etapa) => aceitos.some((c) => c.etapa === etapa) || !!doPainel[etapa];
if (plano.atlas) {
  if (!decidiuAgora('diagnostico')) aprov.diagnostico = pendente({ escopo: '' });
  if (!plano.ciro) {
    delete anteriores.ciro;
    if (!decidiuAgora('fila')) aprov.fila = pendente();
  }
}
if (plano.atlas || plano.ciro) {
  if (plano.ciro && !decidiuAgora('fila')) aprov.fila = pendente();
  if (!plano.diana) {
    delete anteriores.diana;
    if (!decidiuAgora('plano')) aprov.plano = pendente();
  }
}
if (plano.diana && aprov.plano.status === 'rejeitado' && !decidiuAgora('plano')) aprov.plano = pendente();

// 10) Textos prontos para os prompts
function dataCurta(iso) {
  return iso ? String(iso).slice(0, 16).replace('T', ' ') + ' UTC' : '';
}

function linhaDeAprovacao(rotulo, a) {
  let s = '- ' + rotulo + ': ' + a.status;
  if (a.status !== 'pendente') {
    s += ' em ' + dataCurta(a.quando);
    if (a.escopo) s += ', para ' + a.escopo;
  }
  if (a.nota) s += '. Nota registrada: ' + a.nota;
  return s + '.';
}

const aprovacoesTxt = [
  linhaDeAprovacao('Diagnóstico (decisão do KAM)', aprov.diagnostico),
  linhaDeAprovacao('Fila (decisão do Diretor Regional)', aprov.fila),
  linhaDeAprovacao('Plano (decisão do KAM)', aprov.plano),
  estrito
    ? 'Modo estrito: análises e planos preliminares são permitidos; ' +
'aprovações humanas continuam obrigatórias antes de qualquer execução operacional.'
    : 'Modo proposta: as etapas rodam sem bloqueio e cada saída fica pendente de aprovação.',
].join('\n');

function montarContexto(respostas) {
