// Registra no estado da rodada o que aconteceu com este agente e atualiza o contexto dos próximos.
const AGENTE = 'elias';

const estado = JSON.parse(JSON.stringify($('Guardar Diana').first().json));
const entrada = $input.first().json || {};

const ORDEM = ['atlas', 'vera', 'ciro', 'diana', 'elias'];
const NOMES = { atlas: 'Atlas', vera: 'Vera', ciro: 'Ciro', diana: 'Diana', elias: 'Elias' };
const PAPEIS = {
  atlas: 'Diagnóstico de Risco',
  vera: 'Saúde do Relacionamento',
  ciro: 'Priorização da Fila',
  diana: 'Playbook de Retenção',
  elias: 'Mensuração e Aprendizado',
};

// Alguns modelos devolvem a resposta em partes; aqui tudo vira um texto só.
function textoDe(saida) {
  if (typeof saida === 'string') return saida;
  if (Array.isArray(saida)) return saida.map((p) => (p && typeof p === 'object' ? p.text || '' : String(p))).join('\n');
  return saida == null ? '' : JSON.stringify(saida);
}

// Remove raciocínio exposto pelo modelo e limita o tamanho, para um agente prolixo não inundar os seguintes.
function limpar(texto) {
  const semRaciocinio = String(texto).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  const linhas = semRaciocinio
    .split(/\r?\n/)
    .map((l) => l.replace(/\s+$/, ''))
    .filter((l) => l.trim() !== '');
  let encurtou = false;
  let saida = linhas;
  if (saida.length > 12) {
    saida = saida.slice(0, 12);
    encurtou = true;
  }
  let s = saida.join('\n');
  if (s.length > 3000) {
    s = s.slice(0, 3000);
    encurtou = true;
  }
  return encurtou ? s + '\n[resposta encurtada pelo Orquestrador]' : s;
}

const saida = limpar(textoDe(entrada.output));

let registro;
if (!estado.plano[AGENTE]) {
  const bloqueio = (estado.bloqueios || []).find((b) => b.agente === AGENTE);
  if (bloqueio) registro = { status: 'bloqueado', texto: bloqueio.mensagem };
  else if (estado.anteriores[AGENTE]) registro = { status: 'anterior', texto: estado.anteriores[AGENTE] };
  else registro = { status: 'nao_acionado', texto: 'Não acionado nesta pergunta.' };
} else if (saida !== '') {
  registro = { status: 'ok', texto: saida };
} else {
  let motivo = 'sem resposta do modelo';
  if (entrada.error) motivo = typeof entrada.error === 'string' ? entrada.error : entrada.error.message || 'erro na chamada';
  registro = { status: 'falha', texto: 'Falha ao consultar o agente: ' + String(motivo).slice(0, 200) };
}

estado.respostas[AGENTE] = registro;

const partes = [];
for (const a of ORDEM) {
  const cab = NOMES[a] + ' (' + PAPEIS[a] + ')';
  const r = estado.respostas[a];
  if (r) {
    if (r.status === 'ok') partes.push(cab + ', nesta rodada:\n' + r.texto);
    else if (r.status === 'anterior') partes.push(cab + ', rodada anterior:\n' + r.texto);
    else if (r.status === 'nao_acionado') partes.push(cab + ': não acionado nesta pergunta.');
    else partes.push(cab + ': ' + r.texto);
  } else if (estado.anteriores[a]) {
    partes.push(cab + ', rodada anterior:\n' + estado.anteriores[a]);
  }
}
estado.contextoAgentes = partes.length ? partes.join('\n\n') : 'Nenhuma resposta disponível ainda.';

return [{ json: estado }];

