// Monta a resposta do painel: síntese do Orquestrador, aprovações pendentes (sempre calculadas
// pelo fluxo, nunca pelo modelo) e a saída de cada agente. Também grava a memória da sessão.

// ---------------------------------------------------------------------------
// CONFIGURAÇÃO
// ---------------------------------------------------------------------------
const POSICAO_ORQUESTRADOR = 'fim'; // 'fim' | 'inicio' | 'fora' (fora = não entra na lista "agentes")
const MAX_SESSOES = 40; // sessões guardadas na memória do workflow
// ---------------------------------------------------------------------------

const entrada = $input.first().json || {};

const ORDEM = ['atlas', 'vera', 'ciro', 'diana', 'elias'];
const NOMES = { atlas: 'Atlas', vera: 'Vera', ciro: 'Ciro', diana: 'Diana', elias: 'Elias' };
const PAPEIS = {
  atlas: 'Diagnóstico de Risco',
  vera: 'Saúde do Relacionamento',
  ciro: 'Priorização da Fila',
  diana: 'Playbook de Retenção',
  elias: 'Mensuração e Aprendizado',
};

const estado = JSON.parse(JSON.stringify($('Guardar Elias').first().json));
const ap = estado.aprovacoes;
const avisos = (estado.avisos || []).slice();
const resp = (a) => estado.respostas[a] || { status: 'nao_acionado', texto: 'Não acionado nesta pergunta.' };
const rodou = ORDEM.filter((a) => resp(a).status === 'ok');
const existe = (a) => ['ok', 'anterior'].includes(resp(a).status);

// 1) Aprovações pendentes e etapa que a conversa está aguardando
const pendentes = [];
if (existe('atlas') && ap.diagnostico.status === 'pendente') {
  pendentes.push({ etapa: 'diagnostico', responsavel: 'KAM', acao: 'validar o diagnóstico' });
}
if (existe('ciro') && ap.fila.status === 'pendente') {
  pendentes.push({ etapa: 'fila', responsavel: 'Diretor Regional', acao: 'aprovar a fila' });
}
if (existe('diana') && ap.plano.status === 'pendente') {
  pendentes.push({ etapa: 'plano', responsavel: 'KAM', acao: 'aprovar, ajustar ou rejeitar o plano' });
}
if (rodou.includes('diana')) {
  pendentes.push({
    etapa: 'concessao',
    responsavel: 'Diretor Regional',
    acao: 'aprovar qualquer desconto, crédito ou serviço adicional',
  });
}
if (rodou.includes('elias')) {
  pendentes.push({
    etapa: 'apuracao',
    responsavel: 'Revenue Analytics e Finance',
    acao: 'validar a apuração antes de qualquer divulgação',
  });
}
const proxima = pendentes.find((p) => ['diagnostico', 'fila', 'plano'].includes(p.etapa));
const aguardando = proxima ? proxima.etapa : '';

let passo;
if (aguardando === 'diagnostico') {
  passo =
    'o KAM valida o diagnóstico. Responda "Confirmo o diagnóstico", "Ajusto o diagnóstico: ..." ou "Contesto o diagnóstico: ...".';
} else if (aguardando === 'fila') {
  passo =
    'registre a decisão do Diretor Regional. Responda "Fila aprovada pelo Diretor Regional", "Fila ajustada: ..." ou "Fila rejeitada: ...".';
} else if (aguardando === 'plano') {
  passo = 'o KAM decide o plano. Responda "Aprovo o plano", "Ajusto o plano: ..." ou "Rejeito o plano: ...".';
} else if (ap.diagnostico.status === 'contestado') {
  passo =
    'o motivo da contestação segue para a equipe de dados como rótulo. Para reavaliar a conta, peça "Refaça o diagnóstico".';
} else if (ap.fila.status === 'rejeitada') {
  passo = 'a fila foi rejeitada pelo Diretor Regional. Para reordenar, peça "Refaça a fila" e descreva o ajuste.';
} else if (ap.plano.status === 'rejeitado') {
  passo = 'o plano foi rejeitado pelo KAM. Para um novo rascunho, peça "Refaça o plano" e descreva o ajuste.';
} else if (existe('diana') && ['aprovado', 'ajustado'].includes(ap.plano.status)) {
  passo = 'plano aprovado. A execução e o contato com o cliente são do KAM; registre a execução para a mensuração.';
} else {
  passo = 'sem aprovação pendente. Pergunte sobre risco, prioridade, plano ou resultado de uma conta.';
}

const linhaAprovacoes =
  'Aprovações pendentes: ' +
  (pendentes.length ? pendentes.map((p) => p.responsavel + ' precisa ' + p.acao).join('; ') : 'nenhuma') +
  '.';
const linhaPasso = 'Próximo passo: ' + passo;

// 2) Síntese: usa a do modelo quando existe; senão, uma versão fixa a partir do estado
function textoDe(saida) {
  if (typeof saida === 'string') return saida;
  if (Array.isArray(saida)) return saida.map((p) => (p && typeof p === 'object' ? p.text || '' : String(p))).join('\n');
  return saida == null ? '' : JSON.stringify(saida);
}

function limparSintese(texto) {
  const semRaciocinio = String(texto).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  return semRaciocinio
    .split(/\r?\n/)
    .map((l) => l.replace(/\s+$/, ''))
    .filter((l) => l.trim() !== '')
    .filter((l) => !/^\s*(aprova[cç][oõ]es pendentes|pr[oó]ximo passo)\s*:/i.test(l))
    .slice(0, 6)
    .join('\n');
}

function sinteseFixa() {
  const linhas = [];
  const decisoes = (estado.comandosAceitos || []).map((c) => c.etapa + ' ' + c.status);
  if (decisoes.length) linhas.push('Resposta: decisão registrada (' + decisoes.join('; ') + ').');
  else if (rodou.length) linhas.push('Resposta: veja abaixo o que cada agente respondeu.');
  else if (estado.bloqueios.length) linhas.push('Resposta: a etapa pedida depende de uma aprovação que ainda não foi dada.');
  else if (estado.origemPlano === 'aprovacao') linhas.push('Resposta: nenhuma decisão foi registrada nesta rodada.');
  else linhas.push('Resposta: não identifiquei uma pergunta sobre retenção de contas. Posso ajudar com risco, prioridade, plano ou resultado das contas do ciclo.');
  if (rodou.length) linhas.push('Agentes acionados: ' + rodou.map((a) => NOMES[a]).join(', ') + '.');
  const falhas = ORDEM.filter((a) => resp(a).status === 'falha');
  if (falhas.length) linhas.push('Lacunas: falha ao consultar ' + falhas.map((a) => NOMES[a]).join(', ') + '.');
  return linhas.join('\n');
}

let sintese = limparSintese(textoDe(entrada.output));
if (!sintese) {
  if (estado.usarSintese) avisos.push('A síntese do Orquestrador falhou nesta rodada; usei o resumo fixo.');
  sintese = sinteseFixa();
}
const textoOrquestrador = [sintese, linhaAprovacoes, linhaPasso].join('\n');

// 3) Saída de cada agente, sempre na mesma ordem
const agentes = ORDEM.map((a) => {
  const r = resp(a);
  const texto =
    r.status === 'anterior' ? 'Não acionado nesta rodada: continua valendo a resposta anterior deste agente.' : r.texto;
  return { nome: NOMES[a], papel: PAPEIS[a], texto: texto, status: r.status };
});
const cartaoOrquestrador = {
  nome: 'Orquestrador',
  papel: 'Síntese e aprovações',
  texto: textoOrquestrador,
  status: 'ok',
};
if (POSICAO_ORQUESTRADOR === 'inicio') agentes.unshift(cartaoOrquestrador);
else if (POSICAO_ORQUESTRADOR !== 'fora') agentes.push(cartaoOrquestrador);

// 4) Memória da sessão (só é gravada com o workflow ativo, pela URL de produção)
if (estado.sessaoFixa) {
  try {
    const memoria = $getWorkflowStaticData('global');
    if (!memoria.sessoes) memoria.sessoes = {};
    const guardadas = Object.assign({}, estado.anteriores);
    for (const a of rodou) guardadas[a] = resp(a).texto;
    memoria.sessoes[estado.sessionId] = {
      foco: estado.foco,
      aprovacoes: ap,
      respostas: guardadas,
      aguardando: aguardando,
      ultimaPergunta: estado.pergunta,
      atualizadoEm: new Date().toISOString(),
    };
    const ids = Object.keys(memoria.sessoes);
    if (ids.length > MAX_SESSOES) {
      ids.sort((x, y) => String(memoria.sessoes[x].atualizadoEm).localeCompare(String(memoria.sessoes[y].atualizadoEm)));
      for (const id of ids.slice(0, ids.length - MAX_SESSOES)) delete memoria.sessoes[id];
    }
  } catch (e) {
    avisos.push('Não foi possível gravar a memória da sessão.');
  }
}

return [
  {
    json: {
      status: 200,
      corpo: {
        modelo: estado.modeloLlm,
        agentes: agentes,
        orquestrador: {
          resposta: textoOrquestrador,
          conta_foco: estado.foco,
          plano: estado.plano,
          motivo: estado.motivoPlano,
        },
        aprovacoes: {
          modo: estado.modo,
          diagnostico: ap.diagnostico.status,
          fila: ap.fila.status,
          plano: ap.plano.status,
        },
        aprovacoes_pendentes: pendentes,
        avisos: avisos,
        sessionId: estado.sessionId,
      },
    },
  },
];
